mapper.select:


    inner join sys_user u on u.user_name = ttaskmerge.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    ttaskmerge.del_flag = '0'
     and ttaskmerge.merge_delivery_id = #{mergeDeliveryId}
     and ttaskmerge.merge_delivery_detail_id = #{mergeDeliveryDetailId}
     and ttaskmerge.material_id = #{materialId}
     and ttaskmerge.predict_count = #{predictCount}
     and ttaskmerge.actual_count = #{actualCount}
     and ttaskmerge.status = #{status}
     and ttaskmerge.stock_id = #{stockId}
     and ttaskmerge.wcs_id = #{wcsId}
     and ttaskmerge.tray_id = #{trayId}
     and ttaskmerge.location_id = #{locationId}


${params.dataScope}
